def parse_dsn(dsn: str) -> dict:
    """解析 PostgreSQL 连接串，返回 dict。
    格式：postgresql://user:password@host:port/dbname
    端口缺省时默认 5432，密码可为空。
    """
    dsn = dsn.strip()

    for prefix in ("postgresql://", "postgres://"):
        if dsn.startswith(prefix):
            rest = dsn[len(prefix):]
            break
    else:
        raise ValueError("invalid PostgreSQL DSN")

    dbname = None
    if "/" in rest:
        rest, dbname = rest.split("/", 1)

    user = None
    password = None

    if "@" in rest:
        userinfo, hostport = rest.rsplit("@", 1)
        if ":" in userinfo:
            user, password = userinfo.split(":", 1)
        else:
            user = userinfo
            password = ""
    else:
        hostport = rest

    host = hostport
    port = 5432

    if host.startswith("["):
        bracket_end = host.find("]")
        if bracket_end == -1:
            raise ValueError("invalid host")
        host = host[1:bracket_end]
        port_part = hostport[bracket_end + 1:]
        if port_part:
            if not port_part.startswith(":"):
                raise ValueError("invalid host")
            port = int(port_part[1:])
    elif host.count(":") == 1:
        host, port_str = host.split(":", 1)
        port = int(port_str)
    elif host.count(":") > 1:
        raise ValueError("IPv6 address must be enclosed in brackets")

    return {
        "user": user,
        "password": password,
        "host": host,
        "port": port,
        "dbname": dbname,
    }

